<?php
/** Kelola panduan/rekomendasi. Tabel dibuat secara aditif; tidak menyentuh tabel lama. */
require_once __DIR__.'/../shared/helpers.php';
$user=require_role(['Sub Admin']);
$pdo=db();
$pdo->exec("CREATE TABLE IF NOT EXISTS panduan_rekomendasi (id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, judul VARCHAR(150) NOT NULL, jenis VARCHAR(50) NOT NULL, isi TEXT NOT NULL, tampilkan TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
if(is_post()){
 csrf_check(); $aksi=post_str('aksi'); $id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);
 if($aksi==='hapus' && $id!==false){$st=$pdo->prepare('DELETE FROM panduan_rekomendasi WHERE id=:id');$st->execute([':id'=>$id]);flash($st->rowCount()?'success':'error',$st->rowCount()?'Panduan dihapus.':'Panduan tidak ditemukan.');}
 elseif($aksi==='simpan'){$judulInput=post_str('judul');$jenis=post_str('jenis');$isi=post_str('isi');$tampil=isset($_POST['tampilkan'])?1:0;
  if($judulInput===''||$jenis===''||$isi===''){flash('error','Judul, jenis, dan isi wajib diisi.');}
  elseif($id!==false && $id>0){$st=$pdo->prepare('UPDATE panduan_rekomendasi SET judul=:j,jenis=:t,isi=:i,tampilkan=:v WHERE id=:id');$st->execute([':j'=>$judulInput,':t'=>$jenis,':i'=>$isi,':v'=>$tampil,':id'=>$id]);flash('success','Panduan diperbarui.');}
  else{$st=$pdo->prepare('INSERT INTO panduan_rekomendasi(judul,jenis,isi,tampilkan) VALUES(:j,:t,:i,:v)');$st->execute([':j'=>$judulInput,':t'=>$jenis,':i'=>$isi,':v'=>$tampil]);flash('success','Panduan ditambahkan.');}
 }
 redirect(url('sub-admin/panduan.php'));
}
$editId=get_int('edit');$edit=null;if($editId){$st=$pdo->prepare('SELECT * FROM panduan_rekomendasi WHERE id=:id');$st->execute([':id'=>$editId]);$edit=$st->fetch()?:null;}
$q=get_str('q');$st=$pdo->prepare('SELECT * FROM panduan_rekomendasi'.($q!==''?' WHERE judul LIKE :q OR jenis LIKE :q':'').' ORDER BY updated_at DESC,id DESC');if($q!=='')$st->execute([':q'=>'%'.$q.'%']);else $st->execute();$daftar=$st->fetchAll();$pg=paginasi($daftar);
$judul='Kelola Panduan / Rekomendasi';$halamanAktif='sub-admin/panduan.php';require __DIR__.'/../shared/header.php';
?>
<header class="page-header"><h1>Kelola Panduan / Rekomendasi</h1><p class="page-header__desc">Atur panduan penggunaan dan informasi rekomendasi yang ditampilkan kepada User.</p></header>
<div class="layout-split layout-split--guide"><div class="stack"><form class="toolbar" method="get"><div class="search"><label class="visually-hidden" for="cari">Cari panduan</label><span aria-hidden="true" class="icon icon--search"></span><input class="search__input" id="cari" name="q" placeholder="Cari panduan" type="search" value="<?=esc($q)?>"></div><div class="toolbar__end"><button class="btn btn--primary" type="submit"><span aria-hidden="true" class="icon icon--search"></span> Cari</button></div></form><div class="table-card"><table class="table"><thead><tr><th>Judul</th><th>Jenis</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($pg['items'] as $r):?><tr><td><?=esc($r['judul'])?></td><td><?=esc($r['jenis'])?></td><td><span class="badge <?= $r['tampilkan']?'badge--success':'badge--warning' ?>"><?=$r['tampilkan']?'Ditampilkan':'Disembunyikan'?></span></td><td><div class="actions"><button aria-label="Lihat panduan <?=esc($r['judul'])?>" class="icon-btn js-detail" title="Lihat" type="button" data-judul="<?=esc($r['judul'])?>" data-sub="<?=esc($r['jenis'])?>" data-rows="<?=esc(json_encode([['Jenis',$r['jenis']],['Status',$r['tampilkan']?'Ditampilkan':'Disembunyikan'],['Isi',$r['isi']]],JSON_UNESCAPED_UNICODE))?>" data-ubah="<?=esc(url('sub-admin/panduan.php?edit='.(int)$r['id']))?>"><span aria-hidden="true" class="icon icon--eye"></span></button><a aria-label="Ubah panduan <?=esc($r['judul'])?>" class="icon-btn" title="Ubah" href="<?=esc(url('sub-admin/panduan.php?edit='.(int)$r['id']))?>"><span class="icon icon--edit"></span></a><form method="post" data-confirm="Hapus panduan ini?" data-confirm-name="<?=esc($r['judul'])?>"><?=csrf_field()?><input type="hidden" name="aksi" value="hapus"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button aria-label="Hapus panduan <?=esc($r['judul'])?>" class="icon-btn" type="submit" title="Hapus data"><span class="icon icon--trash"></span></button></form></div></td></tr><?php endforeach;?><?php if(!$daftar):?><tr><td colspan="4" class="empty-state">Belum ada panduan. Tambahkan melalui formulir di samping.</td></tr><?php endif;?></tbody></table></div><?=paginasi_html($pg,'panduan')?></div>
<section class="card"><h2 class="text-h3"><?=$edit?'Edit panduan / rekomendasi':'Tambah panduan / rekomendasi'?></h2><form class="stack" method="post"><?=csrf_field()?><input type="hidden" name="aksi" value="simpan"><input type="hidden" name="id" value="<?= (int)($edit['id']??0)?>"><div class="form-group"><label class="label" for="judul">Judul panduan</label><input class="input" id="judul" style="padding-left:16px" name="judul" maxlength="150" required value="<?=esc($edit['judul']??'')?>"></div><div class="form-group"><label class="label" for="jenis">Jenis</label><select class="select" id="jenis" name="jenis" required><option value="">Pilih jenis</option><?php foreach(['Panduan Penggunaan','Rekomendasi','Informasi'] as $j):?><option value="<?=esc($j)?>" <?=($edit['jenis']??'')===$j?'selected':''?>><?=esc($j)?></option><?php endforeach;?></select></div><div class="form-group"><label class="label" for="isi">Isi panduan</label><textarea class="textarea" id="isi" name="isi" rows="6" required><?=esc($edit['isi']??'')?></textarea></div><label class="radio-card" style="margin-bottom:var(--space-4)"><input type="checkbox" name="tampilkan" value="1" <?=!isset($edit['tampilkan'])||(int)$edit['tampilkan']===1?'checked':''?>> Tampilkan kepada User</label><div class="form-actions"><button class="btn btn--primary" type="submit"><span aria-hidden="true" class="icon icon--check"></span> Simpan</button><?php if($edit):?><a class="btn btn--outline" href="<?=esc(url('sub-admin/panduan.php'))?>"><span aria-hidden="true" class="icon icon--close"></span> Batal</a><?php endif;?></div></form></section></div>
